using System;using System.IO;using System.Text;using System.Collections.Generic;
class NewsPureTest{
 static void Assert(bool ok,string m){if(!ok)throw new Exception(m);}
 static void Reject(Action a){bool rejected=false;try{a();}catch{rejected=true;}Assert(rejected,"Expected rejection");}
 static int Main(string[] args){string xml=File.ReadAllText(args[0]);var items=NewsFeed.Parse(xml);Assert(items.Count==2,"items");foreach(string bad in new[]{"http://raiinman.github.io/news.xml","https://localhost/news","https://127.0.0.1/news","https://raiinman.github.io:444/news","https://x@raiinman.github.io/news","https://raiinman.github.io/news?token=x","https://evil.example/news","https://raw.githubusercontent.com/other/repo/main/news.xml","https://raiinman.github.io/news#x"})Reject(delegate{NewsFeed.Endpoint(bad);});Assert(NewsFeed.Endpoint("https://raiinman.github.io/FlutterDeck/news.xml").Scheme=="https","good url");Assert(NewsFeed.Choose(null)==NewsFeed.DefaultEndpoint&&NewsFeed.Choose("  \r\n")==NewsFeed.DefaultEndpoint&&NewsFeed.Choose(" https://raiinman.github.io/x.xml ")=="https://raiinman.github.io/x.xml","no or blank override means the built-in board");Assert(NewsFeed.Endpoint(NewsFeed.DefaultEndpoint).AbsoluteUri==NewsFeed.DefaultEndpoint,"the built-in board passes the address check unchanged");Reject(delegate{NewsFeed.Parse("<!DOCTYPE news [<!ENTITY x SYSTEM 'file:///test'>]><news version='1'/>");});Reject(delegate{NewsFeed.Parse(xml.Replace("release-0-4-0","notices-and-updates"));});Reject(delegate{NewsFeed.Parse(xml.Replace("2026-11-22T04:56:16Z","yesterday"));});Reject(delegate{NewsFeed.ReadBounded(new MemoryStream(new byte[NewsFeed.MaxBytes+1]));});Reject(delegate{NewsFeed.Parse(xml.Replace("<title>","<title><b>"));});var changed=NewsFeed.Parse(xml.Replace("How updates and notices work","How notices work"));Assert(items[0].Fingerprint!=changed[0].Fingerprint,"changed unread");Assert(NewsFeed.Folder("a")!=NewsFeed.Folder("b"),"cache source separation");string folder=args[1];NewsFeed.SaveCache(folder,xml);Assert(NewsFeed.LoadCache(folder)==xml,"cache roundtrip");NewsFeed.SaveRead(folder,items);var read=NewsFeed.LoadRead(folder);Assert(read.Contains(items[0].Fingerprint)&&!read.Contains(changed[0].Fingerprint),"read versioning");Reject(delegate{NewsFeed.SaveCache(folder,"bad");});Assert(NewsFeed.LoadCache(folder)==xml,"bad feed preserves cache");Assert(NewsFeed.Parse("<news version='1'/>").Count==0,"empty feed");Reject(delegate{NewsFeed.ReadBounded(new MemoryStream(new byte[]{0xC3,0x28}));});
string row="<item id='{0}' kind='update' date='2026-11-15T00:00:00Z'><title>T</title><body>B</body></item>";var many=new StringBuilder("<news version='1'>");for(int i=0;i<50;i++)many.Append(String.Format(row,i));Assert(NewsFeed.Parse(many.ToString()+"</news>").Count==50,"50 items");Reject(delegate{NewsFeed.Parse(many.ToString()+String.Format(row,50)+"</news>");});
string single=String.Format(row,"one");Assert(NewsFeed.Parse("<news version='1'>"+single.Replace(">T<",">"+new string('T',140)+"<").Replace(">B<",">"+new string('B',4000)+"<")+"</news>").Count==1,"field boundary");Reject(delegate{NewsFeed.Parse("<news version='1'>"+single.Replace(">T<",">"+new string('T',141)+"<")+"</news>");});Reject(delegate{NewsFeed.Parse("<news version='1'>"+single.Replace(">B<",">"+new string('B',4001)+"<")+"</news>");});
File.WriteAllText(Path.Combine(folder,"blocked"),"fixture");Reject(delegate{NewsFeed.SaveRead(Path.Combine(folder,"blocked"),items);});File.WriteAllText(Path.Combine(folder,"read.txt"),"corrupt");Reject(delegate{NewsFeed.LoadRead(folder);});NewsFeed.SaveRead(folder,items);
Console.WriteLine("PASS: URL/schema/DTD/duplicate/date/size rejection, source cache, unread edits, offline persistence. No HTTP/GUI executed.");return 0;}
}
